            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perte-Dhexagones-(Royaume).html&quot; title=&quot;La perte d&amp;#39;hexagones&quot;&gt;La perte d&#39;hexagones&lt;/a&gt;&lt;/li&gt;
